// The native mission module loader: the contract a module meets and the interface that checks it
// (DESIGN §5.9 path (b), §6.4, §9). The rules, the file layout and the refusal messages are in
// ModuleContract.md beside this file; the import allow-list is allowlist.txt, generated by
// tools/scr2native/gen_allowlist.py. The real loader is loader/NativeModuleLoader.h's;
// ModuleLoaderMock.h stands in for it in tests.
#pragma once

#include <cstddef>
#include <cstdint>
#include <filesystem>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

// A translated module's guest image (guest/GuestModuleAbi.h): where the lifted mission lives in the
// game's 32-bit guest address space.
struct sfcop_module_guest;

// The scripting library's types. Their definitions are in the SDK's headers, which the repository
// does not hold (DESIGN §12.5); the loader only passes the pointers on.
class tScriptEntry;
class tMissionSpec;

namespace sfcop::scripts {

// ModuleContract.md §1: the two exports of every mission, with C linkage.
using MissionSpecEntryFn = const tMissionSpec *(*)(float version);
using ScriptEntryFn = tScriptEntry *(*)();
inline constexpr std::string_view kMissionSpecEntryName = "MissionSpecEntry";
inline constexpr std::string_view kScriptEntryName = "ScriptEntry";
// A module scr2native translated also exports its guest image under this name: the game calls the
// lifted entry points at the guest addresses it gives, as it calls the original .scr's exports.
inline constexpr std::string_view kGuestImageName = "sfcop_module_guest";

// ModuleContract.md §2: the version tag.
inline constexpr std::string_view kAbiTagName = "sfcop_module_abi";
inline constexpr std::uint32_t kModuleContractVersion = 1;
// The SDK's kCurrentScriptVersion; allowlist.txt's header names the version it was generated from.
inline constexpr float kScriptVersion = 22.0f;

#if defined(__aarch64__) || defined(_M_ARM64)
#define SFCOP_MODULE_ARCH "arm64"
#elif defined(__x86_64__) || defined(_M_X64)
#define SFCOP_MODULE_ARCH "x86_64"
#else
#define SFCOP_MODULE_ARCH "unknown"
#endif
#if defined(__APPLE__)
#define SFCOP_MODULE_SYSTEM "macos-itanium"
#elif defined(_WIN32)
#define SFCOP_MODULE_SYSTEM "windows-msvc"
#elif defined(__linux__)
#define SFCOP_MODULE_SYSTEM "linux-itanium"
#else
#define SFCOP_MODULE_SYSTEM "unknown"
#endif
// The ABI this build compiles modules for and accepts them from: <architecture>-<system>-<C++ ABI>.
inline constexpr std::string_view kHostAbiTag = SFCOP_MODULE_ARCH "-" SFCOP_MODULE_SYSTEM;
#undef SFCOP_MODULE_ARCH
#undef SFCOP_MODULE_SYSTEM

// The exported data symbol sfcop_module_abi. Plain data, no pointers, so the loader reads it from
// the file before mapping the module.
struct ModuleAbiTag {
    char magic[8];                 // "SFCOPMOD", no terminator
    std::uint32_t contractVersion; // kModuleContractVersion
    float scriptVersion;           // kScriptVersion
    char compilerAbi[32];          // kHostAbiTag, NUL-terminated
};
static_assert(sizeof(ModuleAbiTag) == 48, "the tag's layout is part of the contract");

// The tag this build writes into the modules it makes and expects in the modules it loads.
ModuleAbiTag hostAbiTag();

// ModuleContract.md §3: an import of the scripting library or the C runtime is named this prefix
// followed by the original's name for the symbol.
inline constexpr std::string_view kImportPrefix = "sfcop_import:";

// ModuleContract.md §4: module.json.
struct ModuleManifest {
    std::string name;              // the original .scr's name without extension
    std::string sourceSha256;      // lower-case hex digest of that .scr
    std::string translatorVersion; // the scr2native version that made the module
};

// ModuleContract.md §5, in the order the checks are made.
enum class Refusal {
    kNotFound,
    kNoManifest,
    kBadManifest,
    kNotLoadable,
    kNoAbiTag,
    kAbiMismatch,
    kForeignImport,
    kNoEntryPoint,
};

struct LoadError {
    Refusal reason;
    std::string module; // the module's name
    std::string detail; // the symbol, field or values the refusal is about; empty if none
};

// The refusal message: "refused: <module>: ...", worded as ModuleContract.md §5 gives it.
std::string describe(const LoadError &error);

// A sorted symbol list in the allowlist.txt format: one symbol per line, '#' lines and blank lines
// skipped.
class AllowList {
public:
    AllowList() = default;
    static AllowList parse(std::string_view text);
    bool contains(std::string_view symbol) const;
    // Whether a "DLL!Name" entry names this module (`dll` as normalizeModuleName gives it).
    bool namesModule(std::string_view dll) const;
    std::size_t size() const { return symbols_.size(); }

private:
    std::vector<std::string> symbols_;
};

// What verify() reads from a module before running any of it. The real loader fills it from the
// directory and the library file; the mock is given it.
struct ModuleImage {
    std::optional<ModuleManifest> manifest;
    std::string manifestError;                 // the invalid field, when module.json is invalid
    std::string notLoadable;                   // why the file is not a library for this host
    std::optional<ModuleAbiTag> abiTag;        // sfcop_module_abi, if exported
    std::vector<std::string> undefinedSymbols; // in file order, the object format's prefix removed
    std::vector<std::string> exportedSymbols;  // likewise
};

// Checks 2 to 8 of ModuleContract.md §5 on an image: the first that fails, or nothing.
// `allowList` is allowlist.txt; `hostRuntime` is the platform's baseline list (§3 rule 2).
std::optional<LoadError> checkImage(std::string_view module, const ModuleImage &image,
                                    const AllowList &allowList, const AllowList &hostRuntime);

// The first import in `imports` that is not on `allowList`, as a kForeignImport refusal. The
// names are the original's, without kImportPrefix (ModuleContract.md §3 rule 1).
std::optional<LoadError> checkImports(std::string_view module,
                                      const std::vector<std::string> &imports,
                                      const AllowList &allowList);

// ModuleContract.md §3, dynamic lookups: a Windows module name as LoadLibraryA, LoadLibraryExA,
// GetModuleHandleA and GetProcAddress compare it: upper case, no directory, ".DLL" added when it
// has no extension.
std::string normalizeModuleName(std::string_view name);

// ModuleContract.md §3, dynamic lookups, for a module the allow-list may name: `symbol` empty is
// LoadLibraryA, LoadLibraryExA or GetModuleHandleA of `dll`; otherwise GetProcAddress of `symbol`
// ("#n" for an ordinal) in `dll`. A refusal is kForeignImport naming "DLL!symbol", or the module
// name when the allow-list does not name the module. `dll` must not be empty: a lookup in the
// module itself is ModuleLoader::checkLookup's.
std::optional<LoadError> checkDynamicLookup(std::string_view module, std::string_view dll,
                                            std::string_view symbol, const AllowList &allowList);

using ModuleId = std::uint32_t; // 0 is never a loaded module

struct LoadedModule {
    ModuleId id = 0;
    ModuleManifest manifest;
    MissionSpecEntryFn missionSpecEntry = nullptr;
    ScriptEntryFn scriptEntry = nullptr;
    const ::sfcop_module_guest *guest = nullptr; // kGuestImageName, if the module exports it
};

struct LoadResult {
    LoadedModule module;            // valid when error is empty
    std::optional<LoadError> error; // the refusal, if the module was refused
    bool ok() const { return !error.has_value(); }
};

// Loads native mission modules. `library` is the path of the shared library inside its module
// directory (ModuleContract.md §4); the module's name is its stem.
class ModuleLoader {
public:
    virtual ~ModuleLoader() = default;

    // Makes every check of ModuleContract.md §5 without mapping the library or running its code.
    virtual std::optional<LoadError> verify(const std::filesystem::path &library) = 0;

    // verify(), then maps the library and resolves its two entry points. A module already loaded
    // is returned again with the same id.
    virtual LoadResult load(const std::filesystem::path &library) = 0;

    // Releases a loaded module. The caller has dropped every pointer the module returned. An id
    // that is not loaded is ignored.
    virtual void unload(ModuleId id) = 0;

    // The check behind the binding shims for LoadLibraryA, LoadLibraryExA, GetModuleHandleA and
    // GetProcAddress when the loaded module `id` calls them (ModuleContract.md §3): `dll` empty is
    // the module itself, `symbol` empty a module lookup. On a refusal the shim returns null. An id
    // that is not loaded is kNotFound.
    virtual std::optional<LoadError> checkLookup(ModuleId id, std::string_view dll,
                                                 std::string_view symbol) = 0;
};

} // namespace sfcop::scripts
